function key(){return'rota-brasil-'+user.uid}function fresh(){return{xp:0,balance:0,deliveries:0,km:0,city:'Jundiaí',history:[],trip:null,rentalPaidOn:'',truck:'tia',loan:null,companyName:''}}function load(){try{return{...fresh(),...JSON.parse(localStorage.getItem(key()))}}catch{return fresh()}}function save(){localStorage.setItem(key(),JSON.stringify(state));chrome();syncPresence()}
