function tripHome(){const t=state.trip,fromImage=cityImages[t.from],toImage=cityImages[t.to],initial=tripStatus();$('#view').innerHTML=heading('TRABALHO EM ANDAMENTO','Viagem para '+t.to,'Acompanhe os dados da entrega e a evolução do caminhão ao vivo.')+'<section class="live-trip-overview"><div class="trip-route-visual"><div class="trip-city origin" style="--trip-city:url(\''+fromImage+'\')"><span>ORIGEM</span><h2>'+t.from+'</h2><small>PARTIDA</small></div><div class="trip-road"><i></i><div class="trip-truck">🚚</div><b>EM VIAGEM</b><span>'+t.totalKm+' KM</span></div><div class="trip-city destination" style="--trip-city:url(\''+toImage+'\')"><span>DESTINO</span><h2>'+t.to+'</h2><small>ENTREGA</small></div></div><div class="trip-work-data"><div class="cargo-panel"><span>CARGA TRANSPORTADA</span><h2>'+t.cargo+'</h2><p>Contrato de <b>'+(t.company||'empresa local')+'</b></p><dl><div><dt>PAGAMENTO</dt><dd>'+money(t.pay)+'</dd></div><div><dt>EXPERIÊNCIA</dt><dd>+'+t.xp+' XP</dd></div><div><dt>DISTÂNCIA TOTAL</dt><dd>'+t.totalKm+' km</dd></div><div><dt>TEMPO TOTAL</dt><dd>'+formatTime(t.end-t.start)+'</dd></div></dl></div><aside class="live-telemetry"><span class="live-label"><i></i>ACOMPANHAMENTO AO VIVO</span><div><small>TEMPO RESTANTE</small><b id="home-trip-time">'+formatTime(initial.remain)+'</b></div><div><small>DISTÂNCIA RESTANTE</small><b id="home-trip-km">'+initial.km.toFixed(1)+' km</b></div><div class="home-trip-progress"><span><i id="home-trip-bar" style="width:'+Math.round(initial.pct*100)+'%"></i></span><small id="home-trip-percent">'+Math.round(initial.pct*100)+'% DA ROTA CONCLUÍDA</small></div><button data-live-map>ACOMPANHAR NO MAPA</button></aside></div></section>';document.querySelector('[data-live-map]').onclick=()=>location.hash='mapa';const update=()=>{const s=tripStatus();if(!s||s.remain<=0){finishTrip();return}$('#home-trip-time').textContent=formatTime(s.remain);$('#home-trip-km').textContent=s.km.toFixed(1)+' km';$('#home-trip-bar').style.width=Math.round(s.pct*100)+'%';$('#home-trip-percent').textContent=Math.round(s.pct*100)+'% DA ROTA CONCLUÍDA'};mapTimer=setInterval(update,1000)}
function deliveries(){const truck=currentTruck();currentOffers=buildOffers();$('#view').innerHTML=heading('MERCADO DE FRETES','3 entregas em '+state.city,'A duração e o pagamento são calculados pela distância e pela capacidade do seu caminhão.')+'<div class="offer-limit"><b>PRÓXIMA RENOVAÇÃO · <span id="offer-reset">--:--</span></b><span>OFERTAS VÁLIDAS ATÉ <strong id="offer-valid-until">'+nextOfferHour()+'</strong> · ALCANCE '+truck.range+' KM · CAPACIDADE '+truck.capacity.toLocaleString('pt-BR')+' KG</span></div><div class="jobs route-list">'+currentOffers.map(routeCard).join('')+'</div>';bind();updateOfferClock()}
function pathPosition(path,pct){if(path.length<2)return path[0];const lengths=[];let total=0;for(let i=1;i<path.length;i++){const n=activeMap.distance(path[i-1],path[i]);lengths.push(n);total+=n}let target=total*pct;for(let i=0;i<lengths.length;i++){if(target<=lengths[i]){const r=target/lengths[i];return[path[i][0]+(path[i+1][0]-path[i][0])*r,path[i][1]+(path[i+1][1]-path[i][1])*r]}target-=lengths[i]}return path.at(-1)}
function factorySection(name){const factories=factoryData[name]||[];return'<section class="city-factories"><div class="section-head"><h2>FÁBRICAS E INDÚSTRIAS DA REGIÃO</h2><span>'+factories.length+' OPERAÇÕES CADASTRADAS</span></div><div class="factory-grid">'+factories.map(factory=>'<article class="factory-card"><div class="factory-top">'+companyLogo(factory)+'<span>'+factory.sector.toUpperCase()+'</span></div><h3>'+factory.name+'</h3><p>'+factory.products+'</p><small>⌖ '+factory.place+'</small></article>').join('')+'</div></section>'}
function mapPage(){const current=cities[state.city],trip=state.trip,status=tripStatus();$('#view').innerHTML=heading('CENTRAL GEOGRÁFICA','Mapa do Brasil',trip?'Acompanhe seu caminhão em tempo real até '+trip.to+'.':'Arraste para explorar, use os controles de zoom e clique em uma cidade para abrir sua página.')+'<section class="map-shell"><div class="map-toolbar"><div><i></i><span>'+(trip?'VIAGEM EM ANDAMENTO':'POSIÇÃO ATUAL')+'<strong>'+(trip?trip.from+' → '+trip.to:state.city+', SP')+'</strong></span></div>'+(trip?'<div class="trip-summary"><b id="trip-time">'+formatTime(status.remain)+'</b><small id="trip-km">'+status.km.toFixed(1)+' km restantes</small></div>':'')+'<button id="map-current">MINHA POSIÇÃO</button><button id="map-brazil">VER BRASIL INTEIRO</button></div><div id="game-map" aria-label="Mapa interativo do Brasil com a posição atual e cidades disponíveis"></div><div class="map-legend"><span><i class="current-dot"></i>'+(trip?'CAMINHÃO EM MOVIMENTO':'VOCÊ ESTÁ AQUI')+'</span><span><i></i>CIDADE DISPONÍVEL</span><small>CLIQUE NOS PONTOS PARA ABRIR A CIDADE</small></div></section>';if(!window.L){$('#game-map').innerHTML='<p class="map-error">Não foi possível carregar o mapa. Verifique sua conexão.</p>';return}activeMap=L.map('game-map',{zoomControl:true,minZoom:3,maxZoom:14,maxBounds:[[-35.5,-74],[6,-32]],maxBoundsViscosity:.8}).setView([current.lat,current.lng],7);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'© OpenStreetMap'}).addTo(activeMap);Object.entries(cities).forEach(([name,c])=>{const here=name===state.city&&!trip,icon=L.divIcon({className:'city-marker-wrap',html:'<button class="city-marker '+(here?'is-current':'')+'" aria-label="'+name+'"><i></i><span>'+name+'</span></button>',iconSize:[100,48],iconAnchor:[50,24]});L.marker([c.lat,c.lng],{icon,title:name}).addTo(activeMap).on('click',()=>location.hash='cidade/'+encodeURIComponent(name))});let liveMarker;if(trip){const path=trip.path?.length?trip.path:[[cities[trip.from].lat,cities[trip.from].lng],[cities[trip.to].lat,cities[trip.to].lng]];L.polyline(path,{color:'#ff9d42',weight:4,opacity:.8}).addTo(activeMap);const update=()=>{const s=tripStatus();if(!s||s.remain<=0){finishTrip();return}const pos=pathPosition(path,s.pct),icon=L.divIcon({className:'truck-marker-wrap',html:'<div class="truck-marker">🚚<span>'+formatTime(s.remain)+'<small>'+s.km.toFixed(1)+' km</small></span></div>',iconSize:[150,60],iconAnchor:[30,30]});if(liveMarker)liveMarker.setLatLng(pos).setIcon(icon);else liveMarker=L.marker(pos,{icon,zIndexOffset:1000}).addTo(activeMap);$('#trip-time').textContent=formatTime(s.remain);$('#trip-km').textContent=s.km.toFixed(1)+' km restantes'};update();mapTimer=setInterval(update,1000);activeMap.fitBounds(L.latLngBounds(path),{padding:[50,50]})}else{(routes[state.city]||[]).forEach(r=>L.polyline([[current.lat,current.lng],[cities[r.to].lat,cities[r.to].lng]],{color:'#c5f24a',weight:2,opacity:.55,dashArray:'5 7'}).addTo(activeMap))}$('#map-current').onclick=()=>{if(trip&&liveMarker)activeMap.flyTo(liveMarker.getLatLng(),10,{duration:.8});else activeMap.flyTo([current.lat,current.lng],9,{duration:.8})};$('#map-brazil').onclick=()=>activeMap.flyTo([-14.2,-51.9],4,{duration:.8});setTimeout(()=>activeMap.invalidateSize(),50)}
function cityPage(name){const c=cities[name]||cities.Jundiaí,here=name===state.city,direct=(routes[state.city]||[]).find(r=>r.to===name),image=cityImages[name],players=onlinePlayers.filter(player=>player.city===name);if(here&&!players.some(player=>player.uid===user.uid))players.unshift({uid:user.uid,name:user.displayName||'Motorista',photo:user.photoURL||'',level:progress().l,status:state.trip?'Em viagem':'Online'});const info='<dl><div><dt>ESTADO</dt><dd>São Paulo</dd></div><div><dt>POPULAÇÃO</dt><dd>'+c.population+'</dd></div><div><dt>PONTO DE REFERÊNCIA</dt><dd>'+c.landmark+'</dd></div><div><dt>STATUS</dt><dd class="'+(here?'green-text':'')+'">'+(here?'VOCÊ ESTÁ AQUI':direct?direct.km+' KM DE '+state.city.toUpperCase():'SEM ROTA DIRETA')+'</dd></div></dl>'+(here?'<button data-city-jobs>VER SERVIÇOS DESTA CIDADE</button>':direct?'<button data-city-company>VIAJAR COM UM SERVIÇO</button>':'<p class="city-warning">Você precisa aceitar uma entrega conectada para chegar a esta cidade.</p>'),drivers='<div class="drivers-head"><span>'+players.length+' MOTORISTA'+(players.length===1?'':'S')+' REAL NESTA CIDADE</span><i></i></div><div class="driver-list">'+(players.length?players.map(p=>'<article class="driver-row '+(p.uid===user.uid?'you':'')+'"><div class="driver-avatar">'+p.name[0]+'</div><div><b>'+p.name+(p.uid===user.uid?' (você)':'')+'</b><small>Nível '+p.level+'</small></div><span class="'+(p.status==='Online'?'online-driver':'')+'">'+p.status+'</span></article>').join(''):'<p class="no-drivers">Nenhum jogador conectado nesta cidade.</p>')+'</div>';$('#view').innerHTML=heading('GUIA DE DESTINOS',name+', SP',c.tag)+'<section class="city-page '+(image?'has-city-photo':'')+'" '+(image?'style="--city-image:url(\''+image+'\')"':'')+'><div class="city-page-cover"><span>'+(here?'LOCALIZAÇÃO ATUAL':'DESTINO MAPEADO')+'</span><h2>'+name+'</h2><p>'+c.desc+'</p></div><aside><div class="city-tabs"><button class="active" data-city-tab="info">INFORMAÇÕES</button><button data-city-tab="drivers">MOTORISTAS <b>'+players.length+'</b></button></div><div id="city-panel"></div></aside></section>'+factorySection(name)+'<button class="back-map" data-back-map>← VOLTAR AO MAPA</button>';const panel=$('#city-panel'),render=tab=>{panel.innerHTML=tab==='drivers'?drivers:info;document.querySelector('[data-city-jobs]')?.addEventListener('click',()=>location.hash='entregas');document.querySelector('[data-city-company]')?.addEventListener('click',()=>location.hash='empresa/coca-cola')};render('info');document.querySelectorAll('[data-city-tab]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-city-tab]').forEach(x=>x.classList.toggle('active',x===b));render(b.dataset.cityTab)});document.querySelector('[data-factory-active]')?.addEventListener('click',()=>location.hash='empresa/coca-cola');document.querySelector('[data-back-map]').onclick=()=>location.hash='mapa'}
function profile(){const p=progress(),name=user.displayName||'Motorista';$('#view').innerHTML=heading('CARTEIRA PROFISSIONAL','Meu perfil','Seu histórico e evolução como motorista.')+'<div class="profile-grid"><aside class="panel identity"><img class="avatar" src="'+(user.photoURL||avatar(name))+'" alt=""><h2>'+name+'</h2><p>REGISTRO RL-'+user.uid.slice(0,8).toUpperCase()+'</p><div class="profile-data"><div><span>Localização atual</span><b>'+state.city+', SP</b></div><div><span>Saldo</span><b>'+money(state.balance)+'</b></div><div><span>Entregas</span><b>'+state.deliveries+'</b></div><div><span>Distância</span><b>'+state.km+' km</b></div></div></aside><section class="panel profile-main"><h2>PROGRESSÃO DO MOTORISTA</h2><div class="level-row"><div><span>NÍVEL ATUAL</span><b>'+p.l+'</b></div><span>'+p.now+' / '+p.need+' XP</span></div><div class="xpbar"><i style="width:'+p.pct+'%"></i></div><div class="progress-label"><span>'+p.pct+'% concluído</span><span>Progressão infinita e lenta</span></div><div class="milestones"><h2>PLANO DE CARREIRA</h2><div class="milestone done"><i></i><div><b>Motorista contratado</b><small>Entregas com veículo fornecido pela empresa.</small></div></div><div class="milestone '+(p.l>=10?'done':'')+'"><i></i><div><b>Comprar o primeiro caminhão · Nível 10</b><small>Tenha seu veículo e receba uma parcela maior do frete.</small></div></div><div class="milestone '+(p.l>=25?'done':'')+'"><i></i><div><b>Abrir transportadora · Nível 25</b><small>Contrate motoristas e administre sua própria empresa.</small></div></div></div></section></div>'}
function truckPage(){const vehicle={name:'O Velho Companheiro',year:'1994',odometer:'684.230 km',range:'100 km',condition:'Usado · operacional'};$('#view').innerHTML=heading('VEÍCULO ATUAL','Meu caminhão','O primeiro capítulo da sua história na estrada.')+'<section class="truck-page"><div class="inherited-truck"><img src="assets/trucks/caminhao-herdado.png" alt="Caminhão antigo e usado emprestado pela tia do jogador"><span>EMPRESTADO PELA SUA TIA</span></div><aside class="truck-story"><p class="eyebrow">UMA CHANCE EM FAMÍLIA</p><h2>'+vehicle.name+'</h2><p>Este caminhão pertenceu ao seu tio, um caminhoneiro que passou boa parte da vida cruzando as estradas do Brasil. Depois que ele faleceu, sua tia guardou o veículo por algum tempo. Sabendo que você queria começar uma carreira, ela decidiu emprestá-lo para que o velho companheiro voltasse à estrada.</p><p>O acordo é simples: você cuida do caminhão e paga <strong>R$ 700,00 por semana</strong> pelo empréstimo. Assim poderá juntar dinheiro e, no futuro, comprar seu próprio veículo.</p><dl><div><dt>PROPRIETÁRIA</dt><dd>Sua tia</dd></div><div><dt>COBRANÇA</dt><dd>Todo sábado</dd></div><div><dt>ALUGUEL SEMANAL</dt><dd>'+money(700)+'</dd></div><div><dt>ANO</dt><dd>'+vehicle.year+'</dd></div><div><dt>QUILOMETRAGEM</dt><dd>'+vehicle.odometer+'</dd></div><div><dt>CONDIÇÃO</dt><dd>'+vehicle.condition+'</dd></div><div class="range-row"><dt>ALCANCE MÁXIMO</dt><dd>'+vehicle.range+'</dd></div></dl><div class="truck-warning"><b>ALCANCE LIMITADO</b><span>Contratos acima de 100 km não aparecem no mercado enquanto este for seu caminhão.</span></div><button data-jobs>PROCURAR TRABALHOS</button></aside></section>';bind()}
function rankingList(players,type){const value=player=>type==='money'?Number(player.balance)||0:type==='km'?Number(player.km)||0:Number(player.level)||1,sorted=[...players].sort((a,b)=>value(b)-value(a));return sorted.length?sorted.slice(0,50).map((player,index)=>'<article class="rank-player '+(player.uid===user.uid?'is-you':'')+'"><b class="rank-position">'+(index+1)+'</b><img src="'+(player.photo||avatar(player.name))+'" alt=""><div><strong>'+escapeHTML(player.name)+(player.uid===user.uid?' (você)':'')+'</strong><small>'+escapeHTML(player.city)+', SP · '+escapeHTML(player.status||'Offline')+'</small></div><span>'+(type==='money'?money(value(player)):type==='km'?value(player).toLocaleString('pt-BR')+' km':'Nível '+value(player))+'</span></article>').join(''):'<p class="ranking-empty">Nenhum motorista registrado ainda.</p>'}
function ranking(){const current={uid:user.uid,name:user.displayName||'Motorista',photo:user.photoURL||'',level:level(state.xp),balance:state.balance,km:state.km,city:state.city,status:state.trip?'Em viagem':'Online'},players=allPlayers.some(player=>player.uid===user.uid)?allPlayers.map(player=>player.uid===user.uid?{...player,...current}:player):[current,...allPlayers];$('#view').innerHTML=heading('CARREIRA COMPETITIVA','Ranking dos motoristas','Classificação formada exclusivamente pelas contas reais da Rota Loner.')+'<section class="ranking-grid"><div class="ranking-board"><header><div><span>FORTUNAS DA ESTRADA</span><h2>Mais dinheiro</h2></div><b>R$</b></header><div class="ranking-list">'+rankingList(players,'money')+'</div></div><div class="ranking-board"><header><div><span>LENDAS DO ASFALTO</span><h2>Maior nível</h2></div><b>XP</b></header><div class="ranking-list">'+rankingList(players,'level')+'</div></div><div class="ranking-board distance-ranking"><header><div><span>REIS DA RODOVIA</span><h2>Maior distância</h2></div><b>KM</b></header><div class="ranking-list">'+rankingList(players,'km')+'</div></div></section>'}
function truckPageV2(){const truck=currentTruck(),borrowed=state.truck!=='agrale8500';$('#view').innerHTML=heading('VEÍCULO ATUAL','Meu caminhão',borrowed?'O caminhão emprestado que iniciou sua carreira.':'Seu primeiro caminhão próprio.')+'<section class="truck-page"><div class="inherited-truck"><img src="'+truck.image+'" alt="'+truck.name+'"><span>'+(borrowed?'EMPRESTADO PELA SUA TIA':'VEÍCULO PRÓPRIO')+'</span></div><aside class="truck-story"><p class="eyebrow">'+(borrowed?'UMA CHANCE EM FAMÍLIA':'PATRIMÔNIO DO MOTORISTA')+'</p><h2>'+truck.name+'</h2><p>'+(borrowed?'Depois que seu tio faleceu, sua tia emprestou o antigo caminhão para você começar. O acordo custa R$ 700,00 por semana e termina quando você compra seu próprio veículo.':'O Agrale 8500 é compacto, robusto e adequado a entregas urbanas e pequenos trechos rodoviários. Sua capacidade maior aumenta o pagamento dos fretes em 45%.')+'</p><dl><div><dt>PROPRIEDADE</dt><dd>'+(borrowed?'Sua tia':'Sua')+'</dd></div><div><dt>CAPACIDADE DE CARGA</dt><dd>'+truck.capacity.toLocaleString('pt-BR')+' kg</dd></div><div><dt>ALCANCE OPERACIONAL</dt><dd>'+truck.range+' km</dd></div><div><dt>MULTIPLICADOR DE FRETE</dt><dd>'+truck.multiplier.toFixed(2).replace('.',',')+'x</dd></div>'+(borrowed?'<div><dt>ALUGUEL</dt><dd>'+money(700)+' / semana</dd></div>':'<div><dt>MODELO</dt><dd>Agrale 8500 · 4x2</dd></div>')+'</dl><div class="truck-warning"><b>CAPACIDADE E RENDA</b><span>Quanto maior a capacidade útil, maior o valor pago pelas empresas em cada frete.</span></div><button data-jobs>PROCURAR TRABALHOS</button></aside></section>';bind()}
const loanPlans={8:{rate:.08},16:{rate:.18},24:{rate:.30},36:{rate:.48}};function loanQuote(weeks){const plan=loanPlans[weeks],total=Math.round(45000*(1+plan.rate)),weekly=Math.ceil(total/weeks);return{weeks:+weeks,rate:plan.rate,total,weekly}}
function truckShop(){const owned=state.truck==='agrale8500',truck=truckCatalog.agrale8500;$('#view').innerHTML=heading('CONCESSIONÁRIA LONER','Venda de caminhões','Compre veículos para aumentar sua capacidade e o valor dos fretes.')+'<section class="dealer-card"><div class="dealer-photo"><img src="'+truck.image+'" alt="Agrale 8500 com carroceria baú"><span>SEMINOVO</span></div><div class="dealer-info"><p class="eyebrow">CAMINHÃO LEVE · 4X2</p><h2>Agrale 8500</h2><strong class="dealer-price">'+money(truck.price)+'</strong><p>Caminhão compacto para distribuição urbana e trajetos rodoviários curtos. Equipado com carroceria baú para cargas secas.</p><dl><div><dt>CAPACIDADE ÚTIL</dt><dd>'+truck.capacity.toLocaleString('pt-BR')+' kg</dd></div><div><dt>ALCANCE NO JOGO</dt><dd>'+truck.range+' km</dd></div><div><dt>BÔNUS NOS FRETES</dt><dd>+45%</dd></div><div><dt>PBT DA LINHA</dt><dd>8.500 kg</dd></div></dl><button data-buy-truck '+(owned?'disabled':'')+'>'+(owned?'VEÍCULO JÁ ADQUIRIDO':'COMPRAR POR '+money(truck.price))+'</button><small>Seu saldo atual: '+money(state.balance)+'</small></div></section>';document.querySelector('[data-buy-truck]')?.addEventListener('click',buyAgrale)}
function buyAgrale(){if(state.truck==='agrale8500')return;if(state.balance<50000){toast('Saldo insuficiente para comprar o Agrale 8500.');return}state.balance-=50000;state.truck='agrale8500';save();toast('Agrale 8500 comprado! O aluguel da sua tia foi encerrado.');truckShop()}
function bankPage(){const active=state.loan?.active,quote=loanQuote(8);$('#view').innerHTML=heading('BANCO LONER','Crédito para crescer','Financiamento semanal para comprar seu primeiro caminhão.')+(active?'<section class="loan-active"><p class="eyebrow">EMPRÉSTIMO ATIVO</p><h2>'+money(state.loan.remainingBalance)+'</h2><span>SALDO DEVEDOR</span><div><b>'+state.loan.remainingWeeks+'</b><small>PARCELAS RESTANTES</small></div><div><b>'+money(state.loan.weekly)+'</b><small>TODO SÁBADO</small></div><p>As parcelas são cobradas mesmo quando seu saldo estiver insuficiente.</p></section>':'<section class="bank-offer"><div><p class="eyebrow">CRÉDITO PRÉ-APROVADO</p><h2>'+money(45000)+'</h2><p>Escolha o prazo. Quanto maior o número de semanas, maiores serão os juros totais.</p></div><aside><label for="loan-weeks">PRAZO DE PAGAMENTO</label><select id="loan-weeks"><option value="8">8 semanas · 8% de juros</option><option value="16">16 semanas · 18% de juros</option><option value="24">24 semanas · 30% de juros</option><option value="36">36 semanas · 48% de juros</option></select><dl><div><dt>VALOR RECEBIDO</dt><dd>'+money(45000)+'</dd></div><div><dt>TOTAL A PAGAR</dt><dd id="loan-total">'+money(quote.total)+'</dd></div><div><dt>PARCELA SEMANAL</dt><dd id="loan-weekly">'+money(quote.weekly)+'</dd></div></dl><button data-take-loan>CONTRATAR EMPRÉSTIMO</button><small>Débito automático todos os sábados. O saldo poderá ficar negativo.</small></aside></section>');const select=$('#loan-weeks');if(select)select.onchange=()=>{const q=loanQuote(select.value);$('#loan-total').textContent=money(q.total);$('#loan-weekly').textContent=money(q.weekly)};document.querySelector('[data-take-loan]')?.addEventListener('click',takeLoan)}
function takeLoan(){if(state.loan?.active)return;const q=loanQuote($('#loan-weeks').value),p=brazilNow(),today=p.year+'-'+p.month+'-'+p.day;state.balance+=45000;state.loan={active:true,principal:45000,total:q.total,weekly:q.weekly,remainingBalance:q.total,remainingWeeks:q.weeks,rate:q.rate,paidOn:p.weekday==='Sat'?today:''};save();toast('Empréstimo aprovado: '+money(45000)+' adicionados ao saldo.');bankPage()}
function companyPage(){if(!state.companyName){$('#view').innerHTML=heading('SEU PRÓXIMO PASSO','Criar minha empresa','Escolha o nome definitivo da sua transportadora para abrir a página dela.')+'<section class="company-create"><div class="company-create-mark">RL</div><div><p class="eyebrow">FUNDAÇÃO DA TRANSPORTADORA</p><h2>Dê um nome ao seu futuro</h2><p>O nome será registrado nesta conta e aparecerá na página da sua empresa.</p><form id="company-form"><label for="company-name">NOME DA EMPRESA</label><input id="company-name" maxlength="32" minlength="3" autocomplete="organization" placeholder="Ex.: Horizonte Transportes" required><small>Use de 3 a 32 caracteres.</small><button type="submit">CRIAR MINHA EMPRESA</button></form></div></section>';$('#company-form').onsubmit=event=>{event.preventDefault();const name=$('#company-name').value.trim().replace(/\s+/g,' ');if(name.length<3){toast('Digite um nome com pelo menos 3 caracteres.');return}state.companyName=name.slice(0,32);save();toast('Transportadora criada com sucesso!');companyPage()};return}const ownedTrucks=state.truck==='agrale8500'?1:0,name=escapeHTML(state.companyName),initials=state.companyName.split(/\s+/).slice(0,2).map(word=>word[0]).join('').toUpperCase();$('#view').innerHTML=heading('GESTÃO DA TRANSPORTADORA',name,'Acompanhe o patrimônio e o crescimento da sua empresa.')+'<section class="company-dashboard"><header><div class="company-emblem">'+escapeHTML(initials)+'</div><div><span>TRANSPORTADORA DO JOGADOR</span><h2>'+name+'</h2><p>Fundador: '+escapeHTML(user.displayName||'Motorista')+'</p></div></header><div class="company-stats"><article><span>CAMINHÕES REGISTRADOS</span><b>'+ownedTrucks+'</b><small>Somente veículos próprios entram na frota</small></article><article><span>MOTORISTAS CONTRATADOS</span><b>0</b><small>Você ainda trabalha sozinho</small></article><article><span>QUILÔMETROS DA EMPRESA</span><b>'+Number(state.km).toLocaleString('pt-BR')+'</b><small>km percorridos pelo fundador</small></article></div><div class="company-fleet"><div><p class="eyebrow">FROTA DA EMPRESA</p><h3>'+(ownedTrucks?'1 caminhão registrado':'Nenhum caminhão registrado')+'</h3><p>'+(ownedTrucks?'Seu Agrale 8500 está registrado no patrimônio da transportadora.':'O caminhão da sua tia é emprestado e não pertence à empresa. Compre um veículo próprio para iniciar a frota.')+'</p></div><button data-company-shop>VER CAMINHÕES À VENDA</button></div></section>';document.querySelector('[data-company-shop]').onclick=()=>location.hash='concessionaria'}
function updateOfferClock(){const now=new Date(),remain=3600000-(now.getMinutes()*60000+now.getSeconds()*1000+now.getMilliseconds()),minutes=Math.floor(remain/60000),seconds=Math.floor(remain%60000/1000),display=$('#offer-reset'),validUntil=$('#offer-valid-until');if(display)display.textContent=String(minutes).padStart(2,'0')+':'+String(seconds).padStart(2,'0');if(validUntil)validUntil.textContent=nextOfferHour();if(location.hash==='#entregas'&&activeOfferKey&&activeOfferKey!==offerCycleKey())deliveries()}
function previewOffer(i){const offer=currentOffers[i];if(!offer)return;sessionStorage.setItem('rota-loner-preview',JSON.stringify({from:state.city,...offer}));location.hash='previsao'}
async function routePreviewPage(){let offer;try{offer=JSON.parse(sessionStorage.getItem('rota-loner-preview'))}catch{}if(!offer||!cities[offer.from]||!cities[offer.to]){location.hash='entregas';return}const start=cities[offer.from],end=cities[offer.to];$('#view').innerHTML=heading('PLANEJAMENTO DE ROTA','Prévia da viagem','Confira o caminho antes de aceitar o trabalho.')+'<section class="preview-map-shell"><div class="preview-contract">'+companyLogo(offer.company,true)+'<div><span>ROTA PREVISTA</span><h2>'+offer.from+' → '+offer.to+'</h2><p>'+offer.cargo+'</p></div><dl><div><dt>DISTÂNCIA</dt><dd>'+offer.km+' km</dd></div><div><dt>TEMPO ESTIMADO</dt><dd>'+travelTime(offer.km)+'</dd></div><div><dt>PAGAMENTO</dt><dd>'+money(reward(offer.km).pay)+'</dd></div></dl><button data-preview-back>VOLTAR ÀS OFERTAS</button></div><div id="preview-map"></div></section>';document.querySelector('[data-preview-back]').onclick=()=>location.hash='entregas';if(!window.L){$('#preview-map').innerHTML='<p class="map-error">Não foi possível carregar o mapa.</p>';return}activeMap=L.map('preview-map',{zoomControl:true,minZoom:5,maxZoom:16}).setView([start.lat,start.lng],9);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'© OpenStreetMap'}).addTo(activeMap);L.marker([start.lat,start.lng]).addTo(activeMap).bindTooltip('Origem · '+offer.from,{permanent:true,direction:'top'});L.marker([end.lat,end.lng]).addTo(activeMap).bindTooltip('Destino · '+offer.to,{permanent:true,direction:'top'});let path=[[start.lat,start.lng],[end.lat,end.lng]];try{const response=await fetch('https://router.project-osrm.org/route/v1/driving/'+start.lng+','+start.lat+';'+end.lng+','+end.lat+'?overview=full&geometries=geojson'),data=await response.json();if(data.routes?.[0])path=data.routes[0].geometry.coordinates.map(c=>[c[1],c[0]])}catch{}if(location.hash!=='#previsao'||!activeMap)return;L.polyline(path,{color:'#c5f24a',weight:5,opacity:.9}).addTo(activeMap);activeMap.fitBounds(L.latLngBounds(path),{padding:[45,45]});setTimeout(()=>activeMap?.invalidateSize(),50)}
function bind(){document.querySelectorAll('[data-job]').forEach(b=>b.onclick=()=>startTrip(+b.dataset.job,b));document.querySelectorAll('[data-preview]').forEach(b=>b.onclick=()=>previewOffer(+b.dataset.preview));document.querySelectorAll('[data-jobs]').forEach(b=>b.onclick=()=>location.hash='entregas')}
async function startTrip(i,button){if(state.trip)return;const r=currentOffers[i],truck=currentTruck();if(!r||r.km>truck.range){toast('Este caminhão não consegue realizar uma viagem acima de '+truck.range+' km.');return}if(r.offerKey!==offerCycleKey()){deliveries();toast('As ofertas foram renovadas. Escolha um novo trabalho.');return}const from=state.city,startCity=cities[from],endCity=cities[r.to];button.disabled=true;button.textContent='CALCULANDO ROTA...';let path=[[startCity.lat,startCity.lng],[endCity.lat,endCity.lng]],totalKm=r.km;try{const res=await fetch('https://router.project-osrm.org/route/v1/driving/'+startCity.lng+','+startCity.lat+';'+endCity.lng+','+endCity.lat+'?overview=full&geometries=geojson'),data=await res.json(),road=data.routes?.[0];if(road)path=road.geometry.coordinates.map(c=>[c[1],c[0]])}catch{}const rw=reward(totalKm),start=Date.now(),duration=travelMinutes(totalKm);state.trip={from,to:r.to,company:r.company.name,cargo:r.cargo,totalKm,path,start,end:start+duration*60000,pay:rw.pay,xp:rw.xp};save();toast('Frete da '+r.company.name+' iniciado para '+r.to+'. Tempo estimado: '+travelTime(totalKm)+'.');location.hash='mapa'}
function finishTrip(){if(!state.trip)return;const t=state.trip;state.xp+=t.xp;state.balance+=t.pay;state.deliveries++;state.km+=t.totalKm;state.city=t.to;state.history.unshift({from:t.from,to:t.to,km:t.totalKm,pay:t.pay});state.trip=null;save();clearInterval(mapTimer);toast('Entrega concluída! Você chegou a '+t.to+': +'+t.xp+' XP e '+money(t.pay)+'.');location.hash='home'}
function route(){clearInterval(mapTimer);if(activeMap){activeMap.remove();activeMap=null}if(state?.trip&&state.trip.end<=Date.now()){finishTrip();return}const page=location.hash.slice(1)||'home';document.querySelectorAll('[data-page]').forEach(a=>a.classList.toggle('active',a.dataset.page===page));if(page==='perfil')profile();else if(page==='ranking')ranking();else if(page==='caminhao')truckPageV2();else if(page==='concessionaria')truckShop();else if(page==='banco')bankPage();else if(page==='entregas'||page==='empresa/coca-cola')deliveries();else if(page==='previsao')routePreviewPage();else if(page==='mapa')mapPage();else if(page.startsWith('cidade/'))cityPage(decodeURIComponent(page.slice(7)));else if(page==='empresa')companyPage();else if(state.trip)tripHome();else home();$('.sidebar').classList.remove('open')}
function brazilNow(){const parts=Object.fromEntries(new Intl.DateTimeFormat('en-CA',{timeZone:'America/Sao_Paulo',year:'numeric',month:'2-digit',day:'2-digit',weekday:'short',hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23'}).formatToParts(new Date()).filter(p=>p.type!=='literal').map(p=>[p.type,p.value]));return parts}
function updateBrazilClock(){const p=brazilNow(),clock=$('#brasil-clock b');if(clock)clock.textContent=p.day+'/'+p.month+'/'+p.year+' · '+p.hour+':'+p.minute+':'+p.second}
function chargeWeeklyRental(){if(!user||!state)return;const p=brazilNow(),today=p.year+'-'+p.month+'-'+p.day;if(p.weekday!=='Sat')return;const charges=[];if(state.truck!=='agrale8500'&&state.rentalPaidOn!==today&&state.balance>=700){state.balance-=700;state.rentalPaidOn=today;charges.push('aluguel da tia: -'+money(700))}if(state.loan?.active&&state.loan.paidOn!==today){const payment=Math.min(state.loan.weekly,state.loan.remainingBalance);state.balance-=payment;state.loan.remainingBalance=Math.max(0,state.loan.remainingBalance-payment);state.loan.remainingWeeks=Math.max(0,state.loan.remainingWeeks-1);state.loan.paidOn=today;if(state.loan.remainingBalance<=0||state.loan.remainingWeeks<=0)state.loan.active=false;charges.push('parcela do banco: -'+money(payment))}if(!charges.length)return;localStorage.setItem(key(),JSON.stringify(state));chrome();syncPresence();toast('Débito de sábado · '+charges.join(' · ')+'.')}
function enter(u){user=u;state=load();$('#login').classList.add('hidden');$('#app').classList.remove('hidden');chrome();watchPresence();route();updateBrazilClock();chargeWeeklyRental();clearInterval(rentalTimer);rentalTimer=setInterval(()=>{updateBrazilClock();updateOfferClock();chargeWeeklyRental()},1000);document.body.classList.remove('auth-pending')}
function toast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>t.classList.remove('show'),4200)}
$('#google-login').onclick=async()=>{const mobile=matchMedia('(max-width: 820px)').matches||/Android|iPhone|iPad|iPod/i.test(navigator.userAgent);try{await setPersistence(auth,browserLocalPersistence);$('#auth-message').textContent=mobile?'Abrindo o login seguro do Google...':'';if(mobile){await signInWithRedirect(auth,provider);return}await signInWithPopup(auth,provider)}catch(error){console.warn('Falha no login:',error.code||error.message);$('#auth-message').textContent='Não foi possível entrar. Verifique a conexão e tente novamente.'}};$('#profile-shortcut').onclick=()=>location.hash='perfil';$('#menu-toggle').onclick=()=>$('.sidebar').classList.toggle('open');addEventListener('hashchange',route);onAuthStateChanged(auth,u=>{if(u)enter(u);else document.body.classList.remove('auth-pending')});
